require_once __DIR__.'/includes/config.php';require_login();require_permission('products');$uid=(int)$_SESSION['user_id'];$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT);if(!$id){redirect('products.php');}
$q=$pdo->prepare('SELECT * FROM products WHERE id=? AND user_id=?');$q->execute([$id,$uid]);$product=$q->fetch();if(!$product){http_response_code(404);exit('Product not found.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$sku=trim($_POST['sku']??'')?:null;$cost=filter_var($_POST['cost_price']??null,FILTER_VALIDATE_FLOAT);$price=filter_var($_POST['selling_price']??null,FILTER_VALIDATE_FLOAT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$threshold=filter_var($_POST['low_stock_threshold']??null,FILTER_VALIDATE_INT);if($name===''||mb_strlen($name)>160)$errors[]='Enter a product name up to 160 characters.';if($cost===false||$cost<0||$price===false||$price<0)$errors[]='Prices must be valid non-negative amounts.';if($qty===false||$qty<0||$threshold===false||$threshold<0)$errors[]='Quantity and alert threshold must be whole numbers of zero or more.';if(!$errors){try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT quantity,name FROM products WHERE id=? AND user_id=? FOR UPDATE');$lock->execute([$id,$uid]);$current=$lock->fetch();if(!$current)throw new RuntimeException('Product not found.');$before=(int)$current['quantity'];$delta=$qty-$before;$q=$pdo->prepare('UPDATE products SET name=?,sku=?,cost_price=?,selling_price=?,quantity=?,low_stock_threshold=? WHERE id=? AND user_id=?');$q->execute([$name,$sku,$cost,$price,$qty,$threshold,$id,$uid]);if($delta!==0){$m=$pdo->prepare("INSERT INTO inventory_movements(user_id,product_id,product_name,movement_type,quantity_change,quantity_before,quantity_after,reference_type,reference_id,note) VALUES(?,?,?,'manual_adjustment',?,?,?,'product',?,?)");$m->execute([$uid,$id,$name,$delta,$before,$qty,$id,'Stock quantity adjusted manually from product edit form']);}audit_log($pdo,'product_updated','product',(int)$id,'Product '.$name.'; quantity '.$before.' to '.(int)$qty);$pdo->commit();flash('Product updated successfully.');redirect('products.php');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex instanceof PDOException && $ex->getCode()==='23000'?'That SKU already exists in your business.':($ex instanceof RuntimeException?$ex->getMessage():'Unable to update product.');}}$product=array_merge($product,['name'=>$name,'sku'=>$sku,'cost_price'=>$cost,'selling_price'=>$price,'quantity'=>$qty,'low_stock_threshold'=>$threshold]);}
$pageTitle='Edit product';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Edit product</h1><p class="muted mb-0">Update product information and inventory.</p></div><a class="btn btn-outline-secondary" href="products.php">Back to products</a></div><?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?>
<div class="card"><div class="card-body p-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="col-md-6"><label class="form-label">Product name</label><input class="form-control" name="name" maxlength="160" required value="<?=e($product['name'])?>"></div><div class="col-md-6"><label class="form-label">SKU (optional)</label><input class="form-control" name="sku" maxlength="80" value="<?=e($product['sku'])?>"></div><div class="col-md-3"><label class="form-label">Cost price (₦)</label><input class="form-control" type="number" min="0" step="0.01" name="cost_price" required value="<?=e((string)$product['cost_price'])?>"></div><div class="col-md-3"><label class="form-label">Selling price (₦)</label><input class="form-control" type="number" min="0" step="0.01" name="selling_price" required value="<?=e((string)$product['selling_price'])?>"></div><div class="col-md-3"><label class="form-label">Quantity</label><input class="form-control" type="number" min="0" name="quantity" required value="<?=(int)$product['quantity']?>"></div><div class="col-md-3"><label class="form-label">Low-stock alert at</label><input class="form-control" type="number" min="0" name="low_stock_threshold" required value="<?=(int)$product['low_stock_threshold']?>"></div><div class="col-12"><div class="alert alert-info mb-0">Stock quantity changes are recorded in Stock History with the previous quantity, new quantity, and adjustment.</div></div><div class="col-12"><button class="btn btn-primary">Save changes</button> <a class="btn btn-light" href="products.php">Cancel</a></div></form></div></div><?php require __DIR__.'/includes/footer.php';?>
